edits.new:
if (status == VF2_OK) {
    /* 0x1850c is LDA, not LD: r5 receives the address of the
     * inline 16-entry float table at fighter+0x1f8. */
    table = fighter + UINT32_C(0x000001f8);
    status = vf2_model2a_read_u32(machine, table, &r4);
}
